void require(bool condition, const char* message) { if (!condition) { throw std::runtime_error(message); } }
void prefault(const void* mapping, size_t bytes) {
  const auto* data = static_cast<const volatile uint8_t*>(mapping);
  for (size_t offset = 0; offset < bytes; offset += 4096) { (void)data[offset]; }
}
uint64_t ns() {
  return static_cast<uint64_t>(std::chrono::duration_cast<std::chrono::nanoseconds>(
    std::chrono::steady_clock::now().time_since_epoch()).count());
}
uint64_t cpuNs() {
#ifdef _WIN32
  FILETIME created {}, exited {}, kernel {}, user {};
  require(GetThreadTimes(GetCurrentThread(), &created, &exited, &kernel, &user) != FALSE, "CPU clock");
  return ((static_cast<uint64_t>(kernel.dwHighDateTime) << 32) + kernel.dwLowDateTime
    + (static_cast<uint64_t>(user.dwHighDateTime) << 32) + user.dwLowDateTime) * 100;
#else
  timespec time {}; require(clock_gettime(CLOCK_THREAD_CPUTIME_ID, &time) == 0, "CPU clock");
  return static_cast<uint64_t>(time.tv_sec) * 1000000000 + static_cast<uint64_t>(time.tv_nsec);
#endif
}
uint64_t cycles() {
#ifdef _WIN32
  ULONG64 value = 0; require(QueryThreadCycleTime(GetCurrentThread(), &value) != FALSE, "cycles"); return value;
#else
  return 0; // No fabricated CPU-cycle number from elapsed TSC ticks.
#endif
}
struct alignas(64) Sync {
  std::atomic<uint32_t> clientReady { 0 }, hostReady { 0 }, start { 0 }, done { 0 };
  WakeState completed;
  WakeState started;
};
void waitFlag(std::atomic<uint32_t>& flag) {
  const uint64_t start = milliseconds();
  while (!flag.load(std::memory_order_acquire)) {
    require(milliseconds() - start < 10000, "fixture startup/completion timeout");
    std::this_thread::sleep_for(std::chrono::milliseconds(1));
  }
}
void waitSignal(std::atomic<uint32_t>& flag, WakeState& wake, Event& event) {
  const uint64_t start = milliseconds();
  wake.armed.store(1, std::memory_order_seq_cst);
  while (true) {
    const auto epoch = wake.epoch.load(std::memory_order_acquire);
    if (flag.load(std::memory_order_seq_cst)) { break; }
    require(milliseconds() - start < 10000 && event.wait(epoch, 10), "fixture event timeout");
  }
  wake.armed.store(0, std::memory_order_seq_cst);
}
